		FROM DUMMY

mapper.update:
 
		UPDATE CUST_MST SET
		         CUSTNAME    = #{CUSTNAME}
		         ,OWNER    = #{OWNER}
		         ,TAXNAME    = #{TAXNAME}
		         ,SANO    = #{SANO}
		         ,HANDNO    = #{HANDNO}
		         ,SANAME    = #{SANAME}
		         ,SALEPER    = #{SALEPER}
		         ,MCGRADE    = #{MCGRADE}
		         ,MIMC    = #{MIMC}
				,EDITUSERID = #{USER.USERID}
				,EDITDATETIME = DATEFORMAT(GETDATE(),'YYYYMMDDHHNNSS')
		WHERE CUSTCD = #{CUSTCD}

 
		UPDATE CUST_MST SET
				CHK = 'N'
				,EDITUSERID = #{USER.USERID}
				,EDITDATETIME = DATEFORMAT(GETDATE(),'YYYYMMDDHHNNSS')
		WHERE CUSTCD = #{CUSTCD}
